// ── Helper: fetch QA records from the QA service ────────────────────────────

async function fetchQARecords() {
  const data = await listScreenings();
  return { records: (data.screenings || []).map(toRecord), truncated: !!data.truncated };
}

// ── Agent metrics helpers ───────────────────────────────────────────────────


async function fetchProductivity(startDate, endDate) {
  const res = await qaFetch(`/api/metrics/productivity?startDate=${startDate}&endDate=${endDate}`);
  if (!res.ok) {
    if (res.status === 502 || res.status === 504) {
      throw new Error(`Productivity fetch timed out (${res.status}). Try a shorter date range (under 31 days).`);
    }
    throw new Error(`Productivity fetch failed (${res.status})`);
  }
  return res.json();
}

async function fetchUnavailable(startDate, endDate) {
  const res = await qaFetch(`/api/metrics/unavailable?startDate=${startDate}&endDate=${endDate}`);
  if (!res.ok) throw new Error(`Unavailable fetch failed (${res.status})`);
  return res.json();
}

function formatSeconds(sec) {
  if (!sec) return "-";
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  if (h > 0) return `${h}h ${m}m`;
  return `${m}m`;
}

function isoDate(d) {
  return d.toISOString().split("T")[0];
}

// ── Component ───────────────────────────────────────────────────────────────

export default function Dashboard({ refreshKey = 0, onEdit }) {
  const [records, setRecords] = useState([]);
  const [truncated, setTruncated] = useState(false);
  const [teamTab, setTeamTab] = useState("customer_support");
  // nameKey -> team, from the agents the QA service knows
  const [teamByName, setTeamByName] = useState({});
  const [openScreeningId, setOpenScreeningId] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [channelFilter, setChannelFilter] = useState("All");
  const [agentFilter, setAgentFilter] = useState("All");

  // Agent metrics state
  const [metricsRange, setMetricsRange] = useState(() => {
    const end = new Date();
    const start = new Date(end.getTime() - 7 * 24 * 3600 * 1000);
    return { start: isoDate(start), end: isoDate(end) };
  });
  const [productivity, setProductivity] = useState([]);
  const [unavailable, setUnavailable] = useState([]);
  const [metricsLoading, setMetricsLoading] = useState(false);
  const [metricsError, setMetricsError] = useState(null);
  const [expandedAgent, setExpandedAgent] = useState(null);

  useEffect(() => {
    async function load() {
      try {
        const [data, agentData] = await Promise.all([
          fetchQARecords(),
          listAgents().catch(() => ({ agents: [] })),
        ]);
        setRecords(data.records);
        setTruncated(data.truncated);
        setTeamByName(Object.fromEntries((agentData.agents || []).map((a) => [nameKey(a.name), a.team])));
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    }
    load();
  }, [refreshKey]);

  // Team of an agent by name: their saved team, else the starting default.
  const teamOf = useMemo(
    () => (name) => teamByName[nameKey(name)] || defaultTeam(name),
    [teamByName]
  );
  const inTeam = useMemo(() => (team) => teamTab === "all" || team === teamTab, [teamTab]);

  // Load agent metrics when range changes
  useEffect(() => {
    async function loadMetrics() {
      setMetricsLoading(true);
      setMetricsError(null);
      try {
        const [prod, unav] = await Promise.all([
          fetchProductivity(metricsRange.start, metricsRange.end),
          fetchUnavailable(metricsRange.start, metricsRange.end),
        ]);
        setProductivity(prod.agents || []);
        setUnavailable(unav.agents || []);
      } catch (err) {
        setMetricsError(err.message);
      } finally {
        setMetricsLoading(false);
      }
    }
    loadMetrics();
  }, [metricsRange.start, metricsRange.end]);

  // Combined per-agent metrics (productivity + quality + unavailable)
  const agentMetrics = useMemo(() => {
    const byName = {};

    // Seed from productivity (CXone data)
    productivity.forEach((p) => {
      byName[p.agentName] = {
        agentName: p.agentName,
        totalContacts: p.totalContacts || 0,
        byChannel: p.byChannel || {},
        totalHandleSeconds: p.totalHandleSeconds || 0,
        avgHandleSeconds: p.avgHandleSeconds || 0,
        refusedCount: p.refusedCount || 0,
        unavailableSeconds: 0,
        // Quality filled below
        screenings: 0,
        avgScore: null,
        passCount: 0,
        passRate: null,
      };
    });

    // Merge unavailable time
    unavailable.forEach((u) => {
      if (!byName[u.agentName]) {
        byName[u.agentName] = {
          agentName: u.agentName,
          totalContacts: 0, byChannel: {}, totalHandleSeconds: 0, avgHandleSeconds: 0, refusedCount: 0,
          unavailableSeconds: 0, screenings: 0, avgScore: null, passCount: 0, passRate: null,
        };
      }
      byName[u.agentName].unavailableSeconds = u.unavailableSeconds || 0;
    });

    // Merge QA quality from SharePoint records (filter to the same date range)
    const startMs = new Date(metricsRange.start).getTime();
    const endMs = new Date(metricsRange.end).getTime() + 24 * 3600 * 1000; // inclusive end
    records.forEach((r) => {
      const t = r.date?.getTime() || 0;
      if (t < startMs || t > endMs) return;
      const name = r.agentName;
      if (!name) return;
      if (!byName[name]) {
        byName[name] = {
          agentName: name,
          totalContacts: 0, byChannel: {}, totalHandleSeconds: 0, avgHandleSeconds: 0, refusedCount: 0,
          unavailableSeconds: 0, screenings: 0, avgScore: null, passCount: 0, passRate: null,
          screeningRecords: [],
        };
      }
      const agg = byName[name];
      agg.screenings = (agg.screenings || 0) + 1;
      agg._scoreSum = (agg._scoreSum || 0) + (r.scorePercent || 0);
      if (r.passFail === "Pass") agg.passCount = (agg.passCount || 0) + 1;
      if (!agg.screeningRecords) agg.screeningRecords = [];
      agg.screeningRecords.push(r);
    });

    // Finalize averages + sort screenings newest first
    Object.values(byName).forEach((a) => {
      if (a.screenings > 0) {
        a.avgScore = Math.round(a._scoreSum / a.screenings);
        a.passRate = Math.round((a.passCount / a.screenings) * 100);
      }
      if (a.screeningRecords) {
        a.screeningRecords.sort((x, y) => (y.date?.getTime() || 0) - (x.date?.getTime() || 0));
      }
      delete a._scoreSum;
    });

    return Object.values(byName)
      .filter((a) => inTeam(teamOf(a.agentName)))
      .sort((a, b) => b.totalContacts - a.totalContacts);
  }, [productivity, unavailable, records, metricsRange.start, metricsRange.end, teamOf, inTeam]);

  // Screenings in the selected team
  const teamRecords = useMemo(() => records.filter((r) => inTeam(r.team)), [records, inTeam]);

  // Filtered records
  const filtered = useMemo(() => {
    return teamRecords.filter((r) => {
      if (channelFilter !== "All" && r.channel !== channelFilter) return false;
      if (agentFilter !== "All" && r.agentName !== agentFilter) return false;
      return true;
    });
  }, [teamRecords, channelFilter, agentFilter]);

  // Unique agents for dropdown
  const agents = useMemo(() => {
    const names = [...new Set(teamRecords.map((r) => r.agentName).filter(Boolean))];
    return names.sort();
  }, [teamRecords]);

  // Reviewed agents in the current filters (not every agent ever screened)
  const reviewedCount = useMemo(
    () => new Set(filtered.map((r) => r.agentName).filter(Boolean)).size,
    [filtered]
  );

  // Summary stats (based on filtered)
  const stats = useMemo(() => {
    if (filtered.length === 0) return { total: 0, avgScore: 0, passRate: 0, channels: {} };
    const avg = Math.round(filtered.reduce((sum, r) => sum + r.scorePercent, 0) / filtered.length);
    const passCount = filtered.filter((r) => r.passFail === "Pass").length;
    const passRate = Math.round((passCount / filtered.length) * 100);

    const channels = {};
    filtered.forEach((r) => {
      if (!channels[r.channel]) channels[r.channel] = 0;
      channels[r.channel]++;
    });

    return { total: filtered.length, avgScore: avg, passRate, channels };
  }, [filtered]);

  return (
    <div style={s.page}>
      <div style={s.card}>
        <div style={s.header}>
          <h1 style={s.headerTitle}>QA Dashboard</h1>
          <p style={s.headerSub}>Quality Assurance screening results and trends</p>
        </div>

        <div style={s.body}>
          {loading ? (
            <div style={s.center}>
              <div>
                <span style={{ ...s.loadingDot, animationDelay: "0s" }} />
                <span style={{ ...s.loadingDot, animationDelay: "0.2s" }} />
                <span style={{ ...s.loadingDot, animationDelay: "0.4s" }} />
              </div>
              <p style={{ marginTop: 12 }}>Loading screenings from SharePoint...</p>
              <style>{`@keyframes pulse { 0%,100% { opacity:.3 } 50% { opacity:1 } }`}</style>
            </div>
          ) : error ? (
            <div style={s.center}>
              <p style={{ color: COLORS.fail }}>{"\u26A0"} {error}</p>
              <p style={{ fontSize: 13 }}>Make sure you have access to the SharePoint list.</p>
            </div>
          ) : (
            <>
              {records.length === 0 && (
                <div style={{
                  background: COLORS.warningBg,
                  border: `1px solid ${COLORS.clementine}`,
                  borderRadius: 8,
                  padding: "10px 14px",
                  fontSize: 13,
                  color: "#795548",
                  marginBottom: 20,
                }}>
                  No QA screenings submitted yet. Agent productivity from CXone is shown below.
                </div>
              )}

              {/* Team tabs */}
              <div role="tablist" style={{ display: "flex", gap: 8, marginBottom: 20, flexWrap: "wrap" }}>
                {TEAM_TABS.map((t) => (
                  <button
                    key={t.key}
                    type="button"
                    role="tab"
                    aria-selected={teamTab === t.key}
                    onClick={() => { setTeamTab(t.key); setAgentFilter("All"); setExpandedAgent(null); }}
                    style={{
                      padding: "8px 18px", borderRadius: 20, border: "2px solid",
                      borderColor: teamTab === t.key ? COLORS.orange : COLORS.lightGray,
                      background: teamTab === t.key ? "#FEF3E2" : COLORS.white,
                      color: teamTab === t.key ? COLORS.orange : COLORS.midGray,
                      fontSize: 14, fontWeight: 600, fontFamily: FONTS.heading, cursor: "pointer",
                    }}
                  >
                    {t.label}
                  </button>
                ))}
              </div>

              {truncated && (
                <div style={{ fontSize: 12, color: COLORS.midGray, marginBottom: 12 }}>
                  Showing the newest 5,000 screenings.
                </div>
              )}

              {/* Summary Stats */}
              <div style={s.statsRow}>
                <div style={s.statCard(COLORS.orange)}>
                  <p style={s.statNum(COLORS.orange)}>{stats.total}</p>
                  <p style={s.statLabel}>Total Screenings</p>
                </div>
                <div style={s.statCard(COLORS.sky)}>
                  <p style={s.statNum(COLORS.sky)}>{stats.avgScore}%</p>
                  <p style={s.statLabel}>Average Score</p>
                </div>
                <div style={s.statCard(COLORS.green)}>
                  <p style={s.statNum(COLORS.green)}>{stats.passRate}%</p>
                  <p style={s.statLabel}>Pass Rate</p>
                </div>
                <div style={s.statCard(COLORS.gray)}>
                  <p style={s.statNum(COLORS.gray)}>{reviewedCount}</p>
                  <p style={s.statLabel}>Agents Reviewed</p>
                </div>
              </div>

              {/* Channel breakdown pills */}
              {Object.keys(stats.channels).length > 1 && (
                <div style={{ display: "flex", gap: 8, marginBottom: 20 }}>
                  {Object.entries(stats.channels).map(([ch, count]) => (
                    <span
                      key={ch}
                      style={{
                        padding: "4px 12px",
                        borderRadius: 12,
                        fontSize: 12,
                        fontWeight: 600,
                        background: "#FEF3E2",
                        color: COLORS.orange,
                        fontFamily: FONTS.heading,
                      }}
                    >
                      {ch}: {count}
                    </span>
                  ))}
                </div>
              )}

              {/* ── Agent Metrics Section ─────────────────────────── */}
              <div style={{ marginTop: 36, marginBottom: 24 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16, flexWrap: "wrap" }}>
                  <h2 style={{ margin: 0, fontSize: 18, fontFamily: FONTS.heading, color: COLORS.gray }}>
                    Agent Metrics
                  </h2>
                  <div style={{ display: "flex", gap: 8, alignItems: "center", fontSize: 13 }}>
                    <label style={{ color: COLORS.midGray }}>From</label>
                    <input
                      type="date"
                      value={metricsRange.start}
                      onChange={(e) => {
                        const newStart = e.target.value;
                        const startDt = new Date(newStart).getTime();
                        const endDt = new Date(metricsRange.end).getTime();
                        // Cap to 31 days to keep within free-tier backend timeout
                        const maxMs = 31 * 24 * 3600 * 1000;
                        const adjustedEnd = endDt - startDt > maxMs ? isoDate(new Date(startDt + maxMs)) : metricsRange.end;
                        setMetricsRange({ start: newStart, end: adjustedEnd });
                      }}
                      style={{ padding: "6px 10px", border: `1.5px solid ${COLORS.lightGray}`, borderRadius: 6, fontFamily: FONTS.body, fontSize: 13 }}
                    />
                    <label style={{ color: COLORS.midGray }}>To</label>
                    <input
                      type="date"
                      value={metricsRange.end}
                      onChange={(e) => {
                        const newEnd = e.target.value;
                        const startDt = new Date(metricsRange.start).getTime();
                        const endDt = new Date(newEnd).getTime();
                        const maxMs = 31 * 24 * 3600 * 1000;
                        const adjustedStart = endDt - startDt > maxMs ? isoDate(new Date(endDt - maxMs)) : metricsRange.start;
                        setMetricsRange({ start: adjustedStart, end: newEnd });
                      }}
                      style={{ padding: "6px 10px", border: `1.5px solid ${COLORS.lightGray}`, borderRadius: 6, fontFamily: FONTS.body, fontSize: 13 }}
                    />
                    <span style={{ color: COLORS.midGray, fontSize: 11 }}>(max 31 days)</span>
                    {metricsLoading && <span style={{ color: COLORS.midGray, fontSize: 12 }}>Loading…</span>}
                  </div>
                </div>

                {metricsError && (
                  <div style={{
                    background: COLORS.failBg, border: "1px solid #FFCDD2", borderRadius: 8,
                    padding: "10px 14px", color: COLORS.fail, fontSize: 13, marginBottom: 12,
                  }}>
                    {"\u26A0"} {metricsError}
                  </div>
                )}

                {agentMetrics.length === 0 && !metricsLoading ? (
                  <div style={{ padding: 20, textAlign: "center", color: COLORS.midGray, fontSize: 13 }}>
                    No agent data for this date range.
                  </div>
                ) : (
                  <div style={{ overflowX: "auto" }}>
                    <table style={s.table}>
                      <thead>
                        <tr>
                          <th style={{ ...s.th, width: 18 }}></th>
                          <th style={s.th}>Agent</th>
                          <th style={{ ...s.th, textAlign: "right" }}>Contacts</th>
                          <th style={s.th}>By Channel</th>
                          <th style={{ ...s.th, textAlign: "right" }}>Avg Handle</th>
                          <th style={{ ...s.th, textAlign: "right" }}>Total Handle</th>
                          <th style={{ ...s.th, textAlign: "right" }}>Refused</th>
                          <th style={{ ...s.th, textAlign: "right" }}>Unavailable</th>
                          <th style={{ ...s.th, textAlign: "right" }}>QA Screenings</th>
                          <th style={{ ...s.th, textAlign: "right" }}>Avg Score</th>
                          <th style={{ ...s.th, textAlign: "right" }}>Pass Rate</th>
                        </tr>
                      </thead>
                      <tbody>
                        {agentMetrics.map((a) => {
                          const isOpen = expandedAgent === a.agentName;
                          const hasScreenings = (a.screeningRecords || []).length > 0;
                          return (
                            <React.Fragment key={a.agentName}>
                              <tr
                                style={{
                                  cursor: hasScreenings ? "pointer" : "default",
                                  background: isOpen ? "#FFF7ED" : "transparent",
                                }}
                                onClick={() => {
                                  if (!hasScreenings) return;
                                  setExpandedAgent(isOpen ? null : a.agentName);
                                }}
                              >
                                <td style={{ ...s.td, textAlign: "center", color: COLORS.midGray }}>
                                  {hasScreenings ? (isOpen ? "▼" : "▶") : ""}
                                </td>
                                <td style={{ ...s.td, fontWeight: 600, color: COLORS.gray }}>{a.agentName}</td>
                                <td style={{ ...s.td, textAlign: "right" }}>{a.totalContacts}</td>
                                <td style={s.td}>
                                  {Object.entries(a.byChannel || {})
                                    .filter(([, n]) => n > 0)
                                    .map(([ch, n]) => `${ch[0]}${n}`)
                                    .join(" · ") || "-"}
                                </td>
                                <td style={{ ...s.td, textAlign: "right" }}>{formatSeconds(a.avgHandleSeconds)}</td>
                                <td style={{ ...s.td, textAlign: "right" }}>{formatSeconds(a.totalHandleSeconds)}</td>
                                <td style={{ ...s.td, textAlign: "right", color: a.refusedCount > 0 ? COLORS.fail : COLORS.gray }}>
                                  {a.refusedCount}
                                </td>
                                <td style={{ ...s.td, textAlign: "right" }}>{formatSeconds(a.unavailableSeconds)}</td>
                                <td style={{ ...s.td, textAlign: "right" }}>{a.screenings || "-"}</td>
                                <td style={{ ...s.td, textAlign: "right", fontWeight: 600,
                                  color: a.avgScore == null ? COLORS.midGray : a.avgScore >= 80 ? COLORS.green : COLORS.fail,
                                }}>
                                  {a.avgScore == null ? "-" : `${a.avgScore}%`}
                                </td>
                                <td style={{ ...s.td, textAlign: "right", fontWeight: 600,
                                  color: a.passRate == null ? COLORS.midGray : a.passRate >= 80 ? COLORS.green : COLORS.fail,
                                }}>
                                  {a.passRate == null ? "-" : `${a.passRate}%`}
                                </td>
                              </tr>
                              {isOpen && (
                                <tr style={{ background: "#FFFBF5" }}>
                                  <td colSpan={11} style={{ padding: "12px 18px" }}>
                                    <div style={{ fontSize: 12, fontWeight: 700, color: COLORS.gray, marginBottom: 8, textTransform: "uppercase", letterSpacing: 0.5 }}>
                                      {a.agentName}'s Screenings ({a.screeningRecords.length})
                                    </div>
                                    <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
                                      <thead>
                                        <tr>
                                          <th style={{ ...s.th, fontSize: 10 }}>Date</th>
                                          <th style={{ ...s.th, fontSize: 10 }}>Channel</th>
                                          <th style={{ ...s.th, fontSize: 10 }}>Contact ID</th>
                                          <th style={{ ...s.th, fontSize: 10 }}>Evaluator</th>
                                          <th style={{ ...s.th, textAlign: "right", fontSize: 10 }}>Score</th>
                                          <th style={{ ...s.th, textAlign: "right", fontSize: 10 }}>Result</th>
                                        </tr>
                                      </thead>
                                      <tbody>
                                        {a.screeningRecords.map((r) => (
                                          <tr
                                            key={r.id}
                                            onClick={(e) => { e.stopPropagation(); setOpenScreeningId(r.id); }}
                                            style={{ cursor: "pointer" }}
                                          >
                                            <td style={s.td}>{r.date ? r.date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : "-"}</td>
                                            <td style={s.td}>{r.channel}</td>
                                            <td style={{ ...s.td, fontFamily: "monospace", fontSize: 11 }}>{r.contactId || "-"}</td>
                                            <td style={s.td}>{r.evaluatorName || "-"}</td>
                                            <td style={{
                                              ...s.td, textAlign: "right", fontWeight: 700,
                                              color: r.scorePercent >= 80 ? COLORS.green : r.scorePercent < 60 ? COLORS.fail : COLORS.orange,
                                            }}>
                                              {r.scorePercent}%
                                            </td>
                                            <td style={{
                                              ...s.td, textAlign: "right", fontWeight: 600,
                                              color: r.passFail === "Pass" ? COLORS.green : COLORS.fail,
                                            }}>
                                              {r.passFail}
                                            </td>
                                          </tr>
                                        ))}
                                      </tbody>
                                    </table>
                                    {a.screeningRecords.some((r) => r.suggestions) && (
                                      <div style={{ marginTop: 12 }}>
                                        <div style={{ fontSize: 10, fontWeight: 700, color: COLORS.midGray, marginBottom: 4, textTransform: "uppercase", letterSpacing: 0.5 }}>
                                          Suggestions
                                        </div>
                                        {a.screeningRecords.filter((r) => r.suggestions).map((r) => (
                                          <div key={`${r.id}-sug`} style={{
                                            padding: "6px 10px", marginBottom: 4, background: COLORS.white,
                                            borderLeft: `3px solid ${COLORS.orange}`, borderRadius: 4,
                                            fontSize: 12, color: COLORS.gray,
                                          }}>
                                            <div style={{ fontSize: 10, color: COLORS.midGray, marginBottom: 2 }}>
                                              {r.date ? r.date.toLocaleDateString() : ""} {"·"} {r.evaluatorName}
                                            </div>
                                            {r.suggestions}
                                          </div>
                                        ))}
                                      </div>
                                    )}
                                  </td>
                                </tr>
                              )}
                            </React.Fragment>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>

              {/* Filters */}
              <div style={s.filterRow}>
                <span style={s.filterLabel}>Filter:</span>
                <select
                  style={s.filterSelect}
                  value={channelFilter}
                  onChange={(e) => setChannelFilter(e.target.value)}
                >
                  <option value="All">All Channels</option>
                  <option value="Phone">Phone</option>
                  <option value="Chat">Chat</option>
                  <option value="Email">Email</option>
                  <option value="SMS">SMS</option>
                </select>
                <select
                  style={s.filterSelect}
                  value={agentFilter}
                  onChange={(e) => setAgentFilter(e.target.value)}
                >
                  <option value="All">All Agents</option>
                  {agents.map((name) => (
                    <option key={name} value={name}>{name}</option>
                  ))}
                </select>
                <span style={{ fontSize: 13, color: COLORS.midGray }}>
                  Showing {filtered.length} of {teamRecords.length} screenings · click a row for details
                </span>
              </div>

              {/* Results Table */}
              <div style={{ overflowX: "auto" }}>
                <table style={s.table}>
                  <thead>
                    <tr>
                      <th style={s.th}>Date</th>
                      <th style={s.th}>Agent</th>
                      <th style={s.th}>Channel</th>
                      <th style={s.th}>Score</th>
                      <th style={s.th}>Result</th>
                      <th style={s.th}>Evaluator</th>
                      {teamTab === "all" && <th style={s.th}>Team</th>}
                    </tr>
                  </thead>
                  <tbody>
                    {filtered.map((r, i) => (
                      <tr
                        key={r.id || i}
                        onClick={() => setOpenScreeningId(r.id)}
                        title="Open screening details"
                        style={{ background: i % 2 === 0 ? COLORS.white : "#FAFAFA", cursor: "pointer" }}
                      >
                        <td style={s.td}>
                          {r.date ? r.date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : "—"}
                        </td>
                        <td style={{ ...s.td, fontWeight: 600 }}>{r.agentName}</td>
                        <td style={s.td}>
                          <span style={{
                            padding: "2px 8px",
                            borderRadius: 8,
                            fontSize: 12,
                            fontWeight: 600,
                            background: "#FEF3E2",
                            color: COLORS.orange,
                          }}>
                            {r.channel}
                          </span>
                        </td>
                        <td style={{ ...s.td, ...s.scoreCell(r.scorePercent) }}>{r.scorePercent}%</td>
                        <td style={s.td}>
                          <span style={s.badge(r.passFail === "Pass")}>{r.passFail}</span>
                        </td>
                        <td style={s.td}>
                          {r.evaluatorName}
                          {r.edited && <span style={{ marginLeft: 6, fontSize: 11, color: COLORS.sky }}>edited</span>}
                        </td>
                        {teamTab === "all" && <td style={s.td}>{teamLabel(r.team)}</td>}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {filtered.length === 0 && (
                <div style={{ ...s.center, padding: "24px 20px" }}>
                  No screenings match the selected filters.
                </div>
              )}

              {openScreeningId && (
                <ScreeningDetail
                  screeningId={openScreeningId}
                  onClose={() => setOpenScreeningId(null)}
                  onEdit={(screening) => { setOpenScreeningId(null); onEdit && onEdit(screening); }}
                />
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}
